import subprocess
import os
import glob
import time
def task_func(test_dir):
    scripts = glob.glob(os.path.join(test_dir, '*.py'))
    results = {}
    for script in scripts:
        start_time = time.time()
        try:
            subprocess.run(['python', script], check=True, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
        except subprocess.CalledProcessError:
            pass
        end_time = time.time()
        results[os.path.basename(script)] = end_time - start_time
    return results

